package com.hbm.client.missile.launchpad.large;
import com.hbm.client.model.*;import com.hbm.client.missile.completion.MissileRenderer;import com.hbm.missile.completion.MissileContent;import com.hbm.missile.launchpad.large.LargeLaunchPadBlockEntity;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import org.joml.Matrix4f;
/** Source exact seven form-specific pads/pivots/erectors/ropes, interpolated original pivot and lift matrices. */
public final class LargeLaunchPadRenderer implements BlockEntityRenderer<LargeLaunchPadBlockEntity>{private static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/weapons/launch_pad_erector.obj");private static final String[] NAMES={"ABM","Micro","V2","Strong","Huge","Atlas","ABM"},SKINS={"abm","micro","v2","strong","huge","atlas","abm"};private static final double[][] OFFSET={{1.5,1.25},{1.5,1.25},{1.75,1.25},{3,1.5},{3,1.5},{4,1.5},{1.5,1.25}};public LargeLaunchPadRenderer(BlockEntityRendererProvider.Context ctx){}private static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);}public static void part(PoseStack poses,MultiBufferSource buffers,int light,int overlay,String skin,boolean smooth,String...parts){var texture=ResourceLocation.parse("hbm:textures/models/launchpad/"+skin+".png");LegacyObjRenderer.renderOnly(mesh(),poses,buffers.getBuffer(RenderType.entityCutout(texture)),light,overlay,-1,smooth?LegacyObjRenderer.Convention.HFR:LegacyObjRenderer.Convention.HFR_FLAT,parts);}
 @Override public void render(LargeLaunchPadBlockEntity pad,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(pad.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};LegacyContactShadows.render(pad,mesh(),new Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw)),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(yaw));part(poses,buffers,light,overlay,"pad",false,"Pad");if(pad.formFactor>=0&&pad.formFactor<NAMES.length){int i=pad.formFactor;String name=NAMES[i],skin="erector_"+SKINS[i];float angle=pad.prevErector+(pad.erector-pad.prevErector)*partial,lift=pad.prevLift+(pad.lift-pad.prevLift)*partial;poses.pushPose();part(poses,buffers,light,overlay,skin,true,name+"_Pad");if(!pad.toRender.isEmpty()&&pad.erected)part(poses,buffers,light,overlay,skin,true,name+"_Rope");poses.translate(0,OFFSET[i][1],-OFFSET[i][0]);poses.mulPose(Axis.XP.rotationDegrees(-angle));poses.translate(0,-OFFSET[i][1],OFFSET[i][0]);part(poses,buffers,light,overlay,skin,true,name+"_Pivot");poses.translate(0,lift,0);part(poses,buffers,light,overlay,skin,true,name+"_Erector");if(pad.erected){poses.popPose();poses.pushPose();}if(!pad.toRender.isEmpty()&&(pad.erected||pad.readyToLoad)){poses.translate(0,2,0);var kind=MissileContent.kind(pad.toRender);if(kind!=null)MissileRenderer.model(kind,poses,buffers,light,overlay,true);}poses.popPose();}poses.popPose();}
 public static void inventory(PoseStack poses,MultiBufferSource buffers,int light,int overlay){poses.scale(.5F,.5F,.5F);poses.mulPose(Axis.YP.rotationDegrees(90));part(poses,buffers,light,overlay,"pad",true,"Pad");part(poses,buffers,light,overlay,"erector_atlas",true,"Atlas_Pad","Atlas_Erector","Atlas_Pivot");}@Override public boolean shouldRenderOffScreen(LargeLaunchPadBlockEntity pad){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(LargeLaunchPadBlockEntity pad){var p=pad.getBlockPos();return new AABB(p.getX()-10,p.getY(),p.getZ()-10,p.getX()+11,p.getY()+15,p.getZ()+11);}}
